use std::rc::{Rc, Weak};

/// A node in a doubly-linked list (or small graph).
/// - `Rc` gives shared ownership.
/// - `RefCell` allows mutation at runtime.
/// - `Weak` back-pointers prevent reference cycles / leaks.
struct Node<T> {
    value: T,
    next: Option<Rc<RefCell<Node<T>>>>,
    prev: Option<Weak<RefCell<Node<T>>>>,
}

impl<T> Node<T> {
    fn new(value: T) -> Self {
        Self {
            value,
            next: None,
            prev: None,
        }
    }
}

/// A safe doubly-linked list wrapper.
pub struct List<T> {
    head: Option<Rc<RefCell<Node<T>>>>,
    tail: Option<Rc<RefCell<Node<T>>>>,
    len: usize,
}

impl<T> List<T> {
    pub fn new() -> Self {
        Self { head: None, tail: None, len: 0 }
    }

    /// Push to the front.
    pub fn push_front(&mut self, value: T) {
        let new_node = Rc::new(RefCell::new(Node::new(value)));
        match self.head.take() {
            Some(old_head) => {
                old_head.borrow_mut().prev = Some(Rc::downgrade(&new_node));
                new_node.borrow_mut().next = Some(old_head);
                self.head = Some(new_node);
                if self.tail.is_none() {
                    self.tail = Some(new_node.clone());
                }
            }
            None => {
                self.head = Some(new_node.clone());
                self.tail = Some(new_node);
            }
        }
        self.len += 1;
    }

    /// Insert a node after a given reference.
    /// `target` is an `Rc`, so you keep your external reference alive.
    pub fn insert_after(
