        if let Some(tail_rc) = self.tail.as_ref() {
            // SAFETY: `tail_rc` is the only mutable path to the tail node.
            // We are not creating conflicting borrows; we write raw pointers.
            unsafe {
                let tail_ptr: *mut Node = &mut *tail_rc.borrow_mut() as *mut _;
                (*new_node.borrow_mut()).prev = tail_ptr;
                (*tail_ptr).next = Rc::as_ptr(&new_node) as *mut Node;
            }
            // Update links
