struct Graph {
    nodes: Vec<Rc<GraphNode>>,
}

struct GraphNode {
    id: usize,
    label: String,
    // Strong refs to nodes we point TO
    neighbors: RefCell<Vec<Rc<GraphNode>>>,
    // Weak refs to nodes pointing TO us (back-links without cycles)
    back_refs: RefCell<Vec<Weak<GraphNode>>>,
}

impl Graph {
    fn new() -> Self {
        Self { nodes: Vec::new() }
    }

    fn add_node(&mut self, label: &str) -> Rc<GraphNode> {
        let id = self.nodes.len();
        let node = Rc::new(GraphNode {
            id,
            label: label.to_string(),
            neighbors: RefCell::new(Vec::new()),
            back_refs: RefCell::new(Vec::new()),
        });
        self.nodes.push(node.clone());
        node
    }

    /// Connect `from` -> `to`. We store a strong reference in `neighbors`
    /// and a weak back-reference in `to` so we can navigate backward safely.
    fn link(&self, from: &Rc<GraphNode>, to: &Rc<GraphNode>) {
        // Forward link (strong)
        from.neighbors.borrow_mut().push(to.clone());

        // Backward link (weak) — avoids Rc cycles
        to.back_refs.borrow_mut().push(Rc::downgrade(from));
    }

    /// Example mutation: update a neighbor's label via the back-reference.
    fn mutate_via_back_ref(&self, node: &Rc<GraphNode>) {
        let back_refs = node.back_refs.borrow();
        for weak in back_refs.iter() {
            if let Some(parent) = weak.upgrade() {
                // We can borrow parent and child separately because they
                // are different Rc handles (different heap allocations).
                parent.neighbors.borrow(); // read access
                drop(parent.neighbors.borrow()); // explicit drop to show separation

                // Mutation of the original node through its own Rc
                let mut n = node.neighbors.borrow_mut();
                // ... do something with n ...
                println!("Mutated neighbors of {}", node.label);
            }
        }
        drop(back_refs);
    }
}

fn main() {
    let mut g = Graph::new();
    let a = g.add_node("A");
    let b = g.add_node("B");

    g.link(&a, &b);
    g.mutate_via_back_ref(&b);
}
