use std::cell::RefCell;
use std::rc::{Rc, Weak};

#[derive(Debug)]
pub struct Node {
    value: i32,
    next: Option<Rc<RefCell<Node>>>,
    prev: Option<Weak<RefCell<Node>>>,
}

impl Node {
    pub fn new(value: i32) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(Node {
            value,
            next: None,
            prev: None,
        }))
    }

    /// Insert `new` after this node.
    pub fn insert_after(self_node: Rc<RefCell<Self>>, value: i32) {
        let new = Node::new(value);
        let mut this = self_node.borrow_mut();

        // If we have a successor, wire its prev to the new node.
        if let Some(ref next_rc) = this.next {
            next_rc.borrow_mut().prev = Some(Rc::downgrade(&new));
        }

        // Wire new node's pointers.
        new.borrow_mut().prev = Some(Rc::downgrade(&self_node));
        new.borrow_mut().next = this.next.take();

        // Wire our own next pointer.
        this.next = Some(new);
    }

    /// Delete this node and splice its neighbors together.
    pub fn delete(self_node: Rc<RefCell<Self>>) {
        // Take our links out of the borrow guard.
        let (prev_weak, next_rc) = {
            let mut this = self_node.borrow_mut();
            let prev_weak = this.prev.clone();
            let next_rc = this.next.clone();
            this.next = None;
            this.prev = None;
            (prev_weak, next_rc)
        };

        // Upgrade prev (Weak -> Option<Rc>) safely.
        if let Some(prev_weak) = prev_weak {
            if let Some(prev_rc) = prev_weak.upgrade() {
                prev_rc.borrow_mut().next = next_rc.clone();
            }
        }

        // Point successor's prev back to predecessor.
        if let Some(next_rc) = next_rc {
            next_rc.borrow_mut().prev = prev_weak;
        }

        // `self_node` drops here; if nothing else holds it, it's freed.
    }

    /// Print values forward.
    pub fn traverse(start: Rc<RefCell<Node>>) {
        let mut current = Some(start);
        while let Some(rc) = current {
            let val = rc.borrow().value;
            println!("{}", val);
            current = rc.borrow().next.clone();
        }
    }
}

fn main() {
    let a = Node::new(1);
    let b = Node::new(2);

    Node::insert_after(a.clone(), 99); // A -> 99 -> B (once B is linked)
    // Actually let's build a proper 1 -> 2 -> 3 chain:
    let c = Node::new(3);

    // Manual linkage for clarity:
    a.borrow_mut().next = Some(b.clone());
    b.borrow_mut().prev = Some(Rc::downgrade(&a));
    b.borrow_mut().next = Some(c.clone());
    c.borrow_mut().prev = Some(Rc::downgrade(&b));

    println!("Before delete:");
    Node::traverse(a.clone());

    // Delete the middle node (2)
    Node::delete(b.clone());

    println!("After delete:");
    Node::traverse(a.clone()); // Should print 1 then 3
}
```

### Why this works with the borrow checker

- **No lifetimes (`<'a>`) anywhere.** `Rc` owns the data and hands out clones that are reference-counted. The compiler doesn't need to track lexical scopes.
- **`RefCell`** lets you call `.borrow_mut()` inside methods like `delete`. If you accidentally hold two mutable borrows at once (`.borrow_mut()` nested inside another `.borrow_mut()` on the same thread), Rust panics at **run-time** with a clear message — not a 3-hour compile-time wall of lifetime errors.
- **`Weak` for `prev`** breaks the reference cycle (`A -> B -> A`). Without `Weak`, the nodes stay alive forever.

### Critical caveat (don't skip this)

This design is **not reentrant** in the same thread.

