    // Mutate a specific node and its neighbors safely
    fn propagate(&mut self, start: usize) {
        let targets: Vec<usize> = self.nodes[start].out.clone();
        for t in targets {
            self.nodes[t].value += self.nodes[start].value;
        }
    }
}

